import { loadFont as loadCinzel } from "@remotion/google-fonts/Cinzel";
import { loadFont as loadGaramond } from "@remotion/google-fonts/EBGaramond";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// JRE (vestuário "do peão ao rei", luxo silencioso). Série da sigla: E = ESTRATÉGIA (a J = Jornada é o CaraDaJre/JornadaV3).
// Mesma identidade da Jornada: preto, dourado em degradê, Cinzel em caixa alta espaçada + EB Garamond nas frases, peão e coroa.
// Pouco material (só a arte do manifesto) → motion, tudo desenhado:
// E grande → mapa (o sonho é a coroa lá em cima; a estratégia é a rota escolhida entre várias) → tabuleiro visto de cima
// (pensar antes de agir, enxergar a rota, esperar, persistir) → torre de xadrez montada bloco a bloco (algo sólido) →
// tabuleiro em perspectiva que acende, peão andando, obstáculos saindo da frente e a coroa no destino → logo.
// Limpo: fundo escuro liso com luz quente; o texto entra e fica parado; o movimento contínuo fica na câmera e nos desenhos.
// v2 (17/10): o o diretor pediu para eliminar todas as pausas. A voz-v2 é a v1 sem os silêncios (cada pausa virou 0,07 s,
// sem acelerar a fala; (arquivo do cliente)), 25,1 s. As cenas continuam escritas nos tempos da voz v1:
// a tabela V2V1 converte o tempo novo no antigo; as trocas de cena que caíam nas pausas viram cortes rápidos.
// Voz v1: public/jre-e/voz-v1.mp3 (o locutor, multilingual v2, 30,5 s). Tempos = tempos da locução (o vídeo tem LEAD de entrada).

const { fontFamily: CAPS } = loadCinzel("normal", { weights: ["400", "500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF } = loadGaramond("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SERIF_I } = loadGaramond("italic", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });

export const JREE2_FPS = 30;
const JREE_FPS = JREE2_FPS;
// [tempo na voz v2, tempo na voz v1]; depois do fim da fala, inclinação 1
const V2V1: [number, number][] = [[0.0, 0.0], [0.35, 0.35], [0.42, 0.91], [1.86, 2.35], [1.93, 3.0], [3.21, 4.28], [3.28, 4.46], [4.74, 5.92], [4.81, 6.42], [8.87, 10.48], [8.94, 11.02], [10.25, 12.33], [10.32, 12.74], [12.51, 14.93], [12.58, 15.42], [13.46, 16.3], [13.53, 16.75], [14.54, 17.76], [14.61, 18.2], [17.36, 20.95], [17.43, 21.37], [19.04, 22.98], [19.11, 23.28], [20.23, 24.4], [20.3, 24.98], [22.85, 27.53], [22.92, 27.9], [25.14, 30.12]];
const toV1 = (t: number) => {
  if (t <= 0) return t;
  for (let i = 1; i < V2V1.length; i++) if (t <= V2V1[i][0]) { const [a0, b0] = V2V1[i - 1], [a1, b1] = V2V1[i]; return b0 + ((t - a0) / (a1 - a0)) * (b1 - b0); }
  const [a, b] = V2V1[V2V1.length - 1]; return t - a + b;
};
const LEAD = 0.15;
const VOZ2 = 25.14;
const END = 30.6 + 3.25 - 30.12;   // o logo entra 0,48 s depois do fim da fala e fica 3,25 s
export const JREE2_FRAMES = Math.round((LEAD + VOZ2 + END) * JREE_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.6) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const BG = "#0A0806";
