const GOLD_GRAD = "linear-gradient(100deg,#8E6A2F 0%,#C9A25A 22%,#F6E2B0 40%,#FFF4D6 46%,#E2C17D 56%,#B08A45 78%,#8E6A2F 100%)";

// trocas de cena
const T2 = 2.75, T3 = 10.75, T4 = 18.05, T5 = 21.2, T6 = 30.6;

const gold = (t: number, speed = 0.18, off = 0): React.CSSProperties => ({
