  const o = out === undefined ? 0 : lin(t, out, out + 0.25);
  return { opacity: Math.min(1, e * 1.5) * (1 - o), filter: `blur(${((1 - e) * 16 + o * 14).toFixed(1)}px)`, transform: `scale(${(1.22 - 0.22 * e + 0.06 * o).toFixed(4)})` };
};

