// rota (lista de pontos): pedaço até a fração p e ponto na fração p
type P2 = [number, number];
const lens = (pts: P2[]) => { const L = [0]; for (let i = 1; i < pts.length; i++) L.push(L[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1])); return L; };
const along = (pts: P2[], p: number): P2 => {
  const L = lens(pts), d = Math.max(0, Math.min(1, p)) * L[L.length - 1];
  for (let i = 1; i < pts.length; i++) if (d <= L[i]) { const f = (d - L[i - 1]) / (L[i] - L[i - 1] || 1); return [pts[i - 1][0] + f * (pts[i][0] - pts[i - 1][0]), pts[i - 1][1] + f * (pts[i][1] - pts[i - 1][1])]; }
  return pts[pts.length - 1];
};
const upTo = (pts: P2[], p: number): P2[] => {
  const L = lens(pts), d = Math.max(0, Math.min(1, p)) * L[L.length - 1];
  const out: P2[] = [pts[0]];
  for (let i = 1; i < pts.length; i++) { if (L[i] <= d) out.push(pts[i]); else { out.push(along(pts, p)); break; } }
  return out;
};
const ptsStr = (a: P2[]) => a.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ");

// ───────── cena 1: É de Estratégia ─────────
const Abertura: React.FC<{ t: number }> = ({ t }) => {
  const e = k(t, -0.3, 0.7);
  const ex = io(t, T2 - 0.25, T2 + 0.3);                 // mergulho dentro do E
  const cam = 1 + 0.1 * io(t, -0.4, 1.0) + 0.1 * k(t, 0.99, 0.5) + 0.14 * k(t, 1.47, 0.7) + 0.05 * lin(t, 2.0, T2) + ex * 2.4;
  const rot = 4 * (1 - k(t, -0.3, 1.2)) + 2.5 * lin(t, 0.3, 1.47) - 3.5 * k(t, 1.47, 0.6) - 1.5 * lin(t, 2.0, T2);
  const shaft = interpolate(t, [-0.4, 1.3, 1.31, T2], [-760, 760, -760, 760], { ...cl, easing: INOUT });
  const letters = "ESTRATÉGIA".split("");
  return (
    <AbsoluteFill style={{ opacity: 1 - lin(t, T2, T2 + 0.3), transform: `scale(${cam.toFixed(4)}) rotate(${rot.toFixed(2)}deg)`, transformOrigin: "540px 820px" }}>
      <Glow y={840} r={620 + 60 * Math.sin(t * 1.6)} a={0.2 * e} />
      <div style={{ position: "absolute", left: 540 - 170 + shaft, top: -300, width: 340, height: 2600, transform: "rotate(-18deg)", background: "linear-gradient(90deg, rgba(255,215,150,0) 0%, rgba(255,215,150,0.09) 50%, rgba(255,215,150,0) 100%)" }} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 360, textAlign: "center", fontFamily: CAPS, fontWeight: 500, fontSize: 720, lineHeight: 1,
        ...gold(t, 0.55, 40), opacity: Math.min(1, e * 1.4), filter: `blur(${((1 - e) * 26).toFixed(1)}px)`, transform: `translateY(${((1 - e) * 260).toFixed(1)}px) scale(${(2.2 - 1.2 * e).toFixed(4)})` }}>E</div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 1150, textAlign: "center", fontFamily: SERIF_I, fontWeight: 500, fontSize: 64, color: CREAM, ...blurIn(t, 0.95, undefined, 0.45) }}>de</div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 1250, display: "flex", justifyContent: "center" }}>
        {letters.map((c, i) => (
          <span key={i} style={{ fontFamily: CAPS, fontWeight: 500, fontSize: 80, letterSpacing: "0.16em", marginRight: i === letters.length - 1 ? "-0.16em" : 0, ...gold(t, 0.2, i * 12), ...blurIn(t, 1.45 + i * 0.045, undefined, 0.55) }}>{c}</span>
        ))}
      </div>
      <div style={{ position: "absolute", left: 540 - 320 * k(t, 1.8, 0.8), width: 640 * k(t, 1.8, 0.8), top: 1385, height: 2, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />
    </AbsoluteFill>
  );
};

// ───────── cena 2: o sonho lá em cima e a rota escolhida ─────────
const PAWN0: P2 = [540, 1640];
const GOAL: P2 = [540, 1010];
const ROUTES: P2[][] = [
  [PAWN0, [300, 1500], [220, 1330], [300, 1170], GOAL],
  [PAWN0, [780, 1520], [860, 1380], [700, 1260], [860, 1130], GOAL],
  [PAWN0, [540, 1480], [700, 1380], [380, 1260], [540, 1140], GOAL],
];
const CHOSEN = [PAWN0, [420, 1530], [660, 1420], [420, 1300], [660, 1180], GOAL] as P2[];
const Mapa: React.FC<{ t: number }> = ({ t }) => {
  const enter = io(t, T2 - 0.05, T2 + 0.5);
  const exit = io(t, T3 - 0.3, T3 + 0.3);
  const dream = k(t, 3.85, 0.9);
  const draw = io(t, 7.25, 8.3);
  const travel = io(t, 8.6, 9.95);
  const crownDrop = io(t, 9.95, 10.3);
  const flash = Math.max(0, 1 - Math.abs(t - 10.3) / 0.22) * 0.22;
  const [pxx, pyy] = along(CHOSEN, travel);
  const ph = 190;
  // câmera: começa no peão, sobe até a coroa (o sonho), volta, abre no mapa e acompanha o peão
  const sc = 1.45 - 0.2 * io(t, 3.85, 4.9) - 0.25 * io(t, 6.2, 7.0) + 0.1 * io(t, 7.0, 8.6) + 0.1 * io(t, 8.6, 9.9) + 0.06 * k(t, 10.25, 0.4) + 0.05 * (1 - enter);
  const fyA = interpolate(t, [T2, 3.85, 4.9, 6.2, 7.2], [1560, 1560, 1000, 1240, 1330], { ...cl, easing: INOUT });
  const fy = fyA * (1 - travel) + (pyy - 80) * travel * 0.6 + fyA * travel * 0.4;
  const fx = 540 + (pxx - 540) * 0.35 * travel;
  const rot = -3 + 5 * lin(t, T2, T3) - 3 * io(t, 6.6, 8.6) - 2 * k(t, 10.25, 0.4);
  const tx = 540 - fx * sc, ty = 1240 - fy * sc;
  const dots: React.ReactNode[] = [];
  for (let r = 0; r < 6; r++) for (let c = 0; c < 6; c++) {
    const x = 180 + c * 144, y = 1100 + r * 104;
    const a = k(t, 4.47 + 0.03 * (r * 6 + c), 0.4);
    dots.push(<circle key={`${r}-${c}`} cx={x} cy={y} r={4} fill={GOLD} opacity={0.28 * a} />);
  }
  const dim = (i: number) => {
    const p = io(t, 6.45 + i * 0.25, 7.2 + i * 0.25);
    const fade = 1 - 0.65 * lin(t, 7.3, 8.0);
    return <polyline key={i} points={ptsStr(upTo(ROUTES[i], p))} fill="none" stroke="#8A6E3E" strokeWidth={4} strokeDasharray="4 16" strokeLinecap="round" opacity={0.85 * fade} />;
  };
  const nodes = CHOSEN.slice(1, -1).map(([x, y], i) => {
    const lit = k(t, 8.05 + i * 0.12, 0.4);
    return <circle key={i} cx={x} cy={y} r={9 + 5 * lit} fill={lit > 0.01 ? "#F6E2B0" : "none"} opacity={Math.min(1, draw * 3) * (0.3 + 0.7 * lit)} />;
  });
  return (
    <AbsoluteFill style={{ opacity: enter * (1 - exit), filter: exit > 0 ? `blur(${(exit * 16).toFixed(1)}px)` : undefined }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transform: `translate(${tx.toFixed(1)}px, ${ty.toFixed(1)}px) scale(${sc.toFixed(4)}) rotate(${rot.toFixed(2)}deg)`, transformOrigin: "0 0" }}>
        <Glow x={GOAL[0]} y={GOAL[1] - 190} r={360 + 30 * Math.sin(t * 1.8)} a={0.34 * dream} />
        <Glow x={pxx} y={pyy - 90} r={260} a={0.14 * k(t, T2, 0.6)} />
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
          {dots}
          {[0, 1, 2].map(dim)}
          <polyline points={ptsStr(upTo(CHOSEN, draw))} fill="none" stroke="#E9CB86" strokeWidth={7} strokeLinecap="round" strokeLinejoin="round" style={{ filter: "drop-shadow(0 0 10px rgba(255,210,140,0.6))" }} />
          {nodes}
        </svg>
        <div style={{ position: "absolute", left: pxx - (ph * 50) / 140, top: pyy - ph - Math.sin(travel * Math.PI * 4) * 14 * (travel < 1 ? 1 : 0) - 600 * Math.pow(1 - k(t, T2 + 0.15, 0.5), 2), filter: "drop-shadow(0 0 22px rgba(255,210,140,0.4))" }}>
          <Pawn h={ph} id="jree-p1" />
        </div>
        <div style={{ position: "absolute", left: GOAL[0] - ph * 0.3, top: GOAL[1] - ph - (260 + 8 * Math.sin(t * 2)) * (1 - crownDrop) - ph * 0.36 * crownDrop,
          opacity: dream, filter: `blur(${((1 - dream) * 12).toFixed(1)}px) drop-shadow(0 0 24px rgba(255,214,150,0.55))`, transform: `scale(${((1.6 - 0.6 * dream) * (1.5 - 0.5 * crownDrop)).toFixed(3)})`, transformOrigin: "50% 100%" }}>
          <Crown w={ph * 0.6} id="jree-c1" />
        </div>
      </div>
      <AbsoluteFill style={{ background: "#FFE9BF", opacity: flash, mixBlendMode: "screen" }} />
      <TopShade />
      <Block>
        <Line t={t} at={3.03} out={4.25} size={84} segs={[["Não basta apenas"]]} />
        <Line t={t} at={3.85} out={4.25} size={84} segs={[["sonhar.", true]]} />
      </Block>
      <Block>
        <Line t={t} at={4.47} out={6.2} size={84} segs={[["É preciso saber"]]} />
        <Line t={t} at={5.21} out={6.2} size={84} segs={[["como "], ["chegar lá.", true]]} />
      </Block>
      <Block>
        <Line t={t} at={6.45} out={8.25} size={80} segs={[["A "], ["estratégia", true], [" é o caminho"]]} />
        <Line t={t} at={7.65} out={8.25} size={80} segs={[["que você escolhe"]]} />
      </Block>
      <Block>
        <Line t={t} at={8.45} size={80} segs={[["para transformar o desejo"]]} />
        <Line t={t} at={9.81} size={80} segs={[["em "], ["realidade.", true]]} />
      </Block>
    </AbsoluteFill>
  );
};

// ───────── cena 3: o tabuleiro visto de cima ─────────
const CELL = 150;
const cellXY = (c: number, r: number): P2 => [540 + (c - 3.5) * CELL, 1300 + (r - 4) * CELL];
// casa (c, r): canto superior esquerdo em cellXY; centro em +CELL/2
const ctr = (c: number, r: number): P2 => { const [x, y] = cellXY(c, r); return [x + CELL / 2, y + CELL / 2]; };
const Plano: React.FC<{ t: number }> = ({ t }) => {
  const enter = io(t, T3 - 0.3, T3 + 0.5);
  const exit = io(t, T4 - 0.3, T4 + 0.3);
  // peão: começa em (3,6); "agir" → (4,5); "persistir" → sobe (4,4), (4,3), (4,2)
  const s1 = io(t, 11.97, 12.4);
  const hops = [17.1, 17.4, 17.7].map((a) => io(t, a, a + 0.26));
  const col = 3 + s1, row = 6 - s1 - hops.reduce((a, b) => a + b, 0);
  const hopFr = hops.reduce((m, h) => Math.max(m, Math.sin(h * Math.PI)), Math.sin(s1 * Math.PI));
  const [pcx, pcy] = ctr(col, row);
  const ph = 170;
  // fantasmas: as jogadas pensadas antes
  const ghosts: [number, number, number][] = [[2, 5, 11.13], [3, 4, 11.6], [4, 5, 11.86]];
  // a rota que só ele enxerga
  const seen: [number, number, number][] = [[4, 4, 13.88], [4, 3, 14.18], [4, 2, 14.46], [4, 1, 14.68]];
  const dark = 0.62 * io(t, 12.75, 13.3) * (1 - io(t, 15.4, 16.2));
  const wait = io(t, 15.5, 16.75);
  const punch = [17.1, 17.4, 17.7].reduce((acc, a) => acc + 0.06 * k(t, a + 0.2, 0.3) * (1 - lin(t, a + 0.5, a + 1.0)), 0);
  const sc = 1.12 + 0.08 * lin(t, T3, 12.7) - 0.06 * io(t, 12.8, 13.6) + 0.1 * io(t, 15.4, 16.7) + punch + 0.08 * (1 - enter);
  const rot = 9 - 14 * lin(t, T3, T4);
  const fx = 540 * 0.4 + pcx * 0.6, fy = interpolate(t, [T3, 12.8, 13.6, 15.4, 16.7], [pcy - 120, pcy - 120, pcy - 300, pcy - 300, pcy - 80], cl);
  const tx = 540 - fx * sc, ty = 1260 - fy * sc;
  const sq: React.ReactNode[] = [];
  for (let r = -2; r < 10; r++) for (let c = -3; c < 11; c++) {
    const [x, y] = cellXY(c, r);
    sq.push(<rect key={`${r}-${c}`} x={x} y={y} width={CELL} height={CELL} fill={(r + c) % 2 === 0 ? "#2A2013" : "#100C07"} stroke="#D6B169" strokeOpacity={0.22} strokeWidth={1.5} />);
  }
  return (
