        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
          {sq}
          {ghosts.map(([c, r, a], i) => {
            const e = k(t, a, 0.4), chosen = i === 2;
            const o = chosen ? 1 - lin(t, 12.3, 12.5) : 1 - lin(t, 11.97, 12.35);
            const [x0, y0] = ctr(3, 6), [x1, y1] = ctr(c, r);
            const mx = (x0 + x1) / 2 + (y1 - y0) * 0.25, my = (y0 + y1) / 2 - (x1 - x0) * 0.25;
            return (
