                <rect x={x1 - CELL / 2 + 8} y={y1 - CELL / 2 + 8} width={CELL - 16} height={CELL - 16} fill="none" stroke="#E9CB86" strokeOpacity={chosen ? 0.9 : 0.45} strokeWidth={3} rx={6} />
              </g>
            );
          })}
        </svg>
        {ghosts.map(([c, r, a], i) => {
          const [x, y] = ctr(c, r); const e = k(t, a, 0.4) * (1 - lin(t, 11.97, 12.35));
          return <div key={i} style={{ position: "absolute", left: x - (120 * 50) / 140, top: y - 120 + 30, opacity: 0.32 * e, transform: `rotate(${(-rot).toFixed(2)}deg)`, transformOrigin: "50% 100%" }}><Pawn h={120} id={`jree-g${i}`} /></div>;
        })}
        <AbsoluteFill style={{ background: "#050403", opacity: dark }} />
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
          {seen.map(([c, r, a], i) => {
            const [x, y] = cellXY(c, r); const e = k(t, a, 0.45);
            return <rect key={i} x={x + 6} y={y + 6} width={CELL - 12} height={CELL - 12} rx={6} fill={`rgba(233,203,134,${(0.32 * e * (1 - 0.4 * lin(t, 16.2, 17.0))).toFixed(3)})`} stroke="#F6E2B0" strokeOpacity={0.9 * e} strokeWidth={3} style={{ filter: "drop-shadow(0 0 14px rgba(255,214,150,0.6))" }} />;
          })}
          <circle cx={pcx} cy={pcy} r={118} fill="none" stroke="#3A2D18" strokeWidth={6} opacity={k(t, 15.44, 0.3) * (1 - lin(t, 16.8, 17.1))} />
          <circle cx={pcx} cy={pcy} r={118} fill="none" stroke="#F1D695" strokeWidth={6} strokeLinecap="round" pathLength={1} strokeDasharray={`${wait} 1`} transform={`rotate(-90 ${pcx} ${pcy})`} opacity={k(t, 15.44, 0.3) * (1 - lin(t, 16.8, 17.1))} />
