        <div style={{ position: "absolute", left: pcx - (ph * 50) / 140, top: pcy - ph + 34 - hopFr * 60, filter: "drop-shadow(0 0 22px rgba(255,210,140,0.45))", transform: `rotate(${(-rot).toFixed(2)}deg)`, transformOrigin: "50% 100%" }}>
          <Pawn h={ph} id="jree-p2" />
        </div>
      </div>
      <TopShade />
      <Block>
        <Line t={t} at={11.05} out={12.6} size={88} segs={[["É pensar"]]} />
        <Line t={t} at={11.6} out={12.6} size={88} segs={[["antes de "], ["agir.", true]]} />
      </Block>
      <Block>
        <Line t={t} at={12.8} out={15.2} size={84} segs={[["É enxergar o que"]]} />
        <Line t={t} at={13.74} out={15.2} size={84} segs={[["os outros ainda"]]} />
        <Line t={t} at={14.42} out={15.2} size={84} segs={[["não veem.", true]]} />
