};

// ───────── cena 4: a torre montada bloco a bloco ─────────
const GROUND = 1660;
// blocos de baixo para cima: [largura, altura, quando cai]
const BLOCKS: [number, number, number][] = [[470, 90, 18.55], [380, 46, 18.9], [330, 150, 19.45], [330, 150, 19.8], [410, 64, 20.3], [430, 110, 20.62]];
const Torre: React.FC<{ t: number }> = ({ t }) => {
  const enter = io(t, T4 - 0.25, T4 + 0.4);
  const exit = io(t, T5 - 0.3, T5 + 0.25);
  let top = GROUND;
  const tops: number[] = [];
  BLOCKS.forEach(([, h]) => { top -= h; tops.push(top); });
  const built = BLOCKS.reduce((acc, [, h, at]) => acc + h * io(t, at + 0.1, at + 0.7), 0);
  const total = GROUND - tops[tops.length - 1];
  const shake = BLOCKS.reduce((acc, [, , a]) => acc + Math.max(0, 1 - (t - a - 0.22) / 0.25) * (t > a + 0.22 ? 1 : 0), 0);
  const sc = 1.3 - 0.32 * io(t, 18.5, 21.0) + 0.04 * Math.min(1, shake) + 0.06 * (1 - enter);
  const fy = GROUND - 260 + (built / total) * (1300 - (GROUND - 260));
  const rot = -4 + 6 * lin(t, T4, T5) + Math.sin(t * 40) * 0.5 * Math.min(1, shake);
  const tx = 540 - 540 * sc, ty = 1220 - fy * sc;
  return (
    <AbsoluteFill style={{ opacity: enter * (1 - exit), transform: `scale(${(1 + 0.25 * exit).toFixed(3)})`, filter: exit > 0 ? `blur(${(exit * 14).toFixed(1)}px)` : undefined }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, transform: `translate(${tx.toFixed(1)}px, ${ty.toFixed(1)}px) scale(${sc.toFixed(4)}) rotate(${rot.toFixed(2)}deg)`, transformOrigin: "0 0" }}>
        <Glow y={1260} r={560} a={0.12 + 0.22 * k(t, 20.62, 0.8)} />
        <div style={{ position: "absolute", left: 540 - 420 * k(t, T4, 0.8), width: 840 * k(t, T4, 0.8), top: GROUND, height: 2, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />
        <svg width={1080} height={1920} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
          <GradDefs id="jree-tw" />
          {BLOCKS.map(([w, h, a], i) => {
            const fall = interpolate(t, [a - 0.15, a + 0.22], [0, 1], { ...cl, easing: Easing.in(Easing.quad) });
            if (fall <= 0) return null;
            const y = tops[i] - 700 * (1 - fall);
            const x = 540 - w / 2;
            const last = i === BLOCKS.length - 1;
            return (
              <g key={i} opacity={Math.min(1, fall * 3)}>
                {last ? (
                  <path d={`M${x},${y + h} L${x},${y} L${x + 80},${y} L${x + 80},${y + 44} L${x + 175},${y + 44} L${x + 175},${y} L${x + w - 175},${y} L${x + w - 175},${y + 44} L${x + w - 80},${y + 44} L${x + w - 80},${y} L${x + w},${y} L${x + w},${y + h} Z`} fill="url(#jree-tw)" stroke="#5E4520" strokeWidth={2} />
                ) : (
                  <rect x={x} y={y} width={w} height={h} rx={4} fill="url(#jree-tw)" stroke="#5E4520" strokeWidth={2} />
                )}
                {h >= 150 && <>
                  <line x1={x} x2={x + w} y1={y + h / 2} y2={y + h / 2} stroke="#7E5D27" strokeWidth={2} opacity={0.6} />
                  <line x1={x + w / 2} x2={x + w / 2} y1={y} y2={y + h / 2} stroke="#7E5D27" strokeWidth={2} opacity={0.6} />
                  <line x1={x + w / 4} x2={x + w / 4} y1={y + h / 2} y2={y + h} stroke="#7E5D27" strokeWidth={2} opacity={0.6} />
                  <line x1={x + (3 * w) / 4} x2={x + (3 * w) / 4} y1={y + h / 2} y2={y + h} stroke="#7E5D27" strokeWidth={2} opacity={0.6} />
                </>}
              </g>
            );
          })}
        </svg>
      </div>
      <TopShade />
      <Block>
        <Line t={t} at={18.26} size={88} segs={[["Saber cada "], ["passo", true]]} />
        <Line t={t} at={19.66} size={88} segs={[["para construir"]]} />
        <Line t={t} at={20.3} size={88} segs={[["algo "], ["sólido.", true]]} />
      </Block>
    </AbsoluteFill>
  );
};

// ───────── cena 5: o tabuleiro acende, o peão anda e nada desvia ─────────
const BH = 2.3, BF = 820, BHZ = 760;
const Destino: React.FC<{ t: number }> = ({ t }) => {
  const enter = io(t, T5 - 0.2, T5 + 0.5);
  const exit = io(t, T6 - 0.2, T6 + 0.25);
  const STEPS = [25.05, 25.7, 26.35, 27.0, 29.15, 29.4, 29.65];
  let wp = 0.5;
  STEPS.forEach((a, i) => { wp += io(t, a, a + (i < 4 ? 0.5 : 0.22)); });
  const hop = Math.sin((wp - 0.5 - Math.floor(wp - 0.5)) * Math.PI);
  const wc = wp - 5.4 - 2.4 * (1 - io(t, T5, 25.0)) + 0.6 * io(t, 29.9, 30.6);   // a câmera vem chegando até o peão
  // nos obstáculos a câmera vai para o lado, para eles aparecerem ao lado do peão e não escondidos atrás dele
  const camX = 1.6 * (1 - io(t, T5, 22.8)) - 0.9 * io(t, 22.4, 23.8) * (1 - io(t, 23.8, 25.2)) + 0.3 * Math.sin((t - 25) * 1.3) * lin(t, 25, 26) * (1 - lin(t, 27.2, 27.6)) + 1.5 * io(t, 27.4, 28.2) * (1 - io(t, 29.0, 29.8));
  const proj = (X: number, W: number) => { const z = Math.max(0.15, W - wc); return [540 + (BF * (X - camX)) / z, BHZ + (BF * BH) / z]; };
  const light = k(t, 22.1, 1.2);                       // "estratégia": o tabuleiro aparece
  const sq: React.ReactNode[] = [];
  for (let r = -7; r < 10; r++) {
    for (let c = -4; c <= 4; c++) {
      const W0 = r, W1 = r + 1;
      if (W1 - wc < 0.2) continue;
      const W0c = Math.max(W0, wc + 0.2);
      const p = [proj(c - 0.5, W0c), proj(c + 0.5, W0c), proj(c + 0.5, W1), proj(c - 0.5, W1)];
      const z = (W0c + W1) / 2 - wc;
      const reveal = Math.max(0, Math.min(1, light * 9 - Math.hypot(c, r - 2) * 0.9));
      const fade = Math.min(1, 2.8 / z) * (1 - Math.abs(c) / 6) * reveal;
      const lane = c === 0 && r >= 1 && r <= 8 ? k(t, 23.3 + (r - 1) * 0.1, 0.4) : 0;
      sq.push(<polygon key={`${r}${c}`} points={p.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(" ")} fill={lane > 0 ? `rgba(214,177,105,${(0.08 + 0.2 * lane * Math.min(1, 2.5 / z)).toFixed(3)})` : (r + c) % 2 === 0 ? "#2C2214" : "#0F0B07"}
        stroke="#D6B169" strokeOpacity={(0.3 + 0.4 * lane) * fade} strokeWidth={1.5} opacity={Math.min(1, 0.15 + fade)} />);
    }
  }
  const [bx, by] = proj(0, wp);
  const ph = (BF * 1.25) / (wp - wc);
  // obstáculos: sobem na frente em "nenhum obstáculo" e saem de lado em "desvia"
  const obs: [number, number, number, number][] = [[5.5, 27.93, 28.95, -1], [6.5, 28.23, 29.05, 1]];
  const goalW = 8;
  const crownIn = k(t, 23.9, 0.8);
  const crownDrop = io(t, 29.95, 30.3);
  const flash = Math.max(0, 1 - Math.abs(t - 30.3) / 0.22) * 0.22;
  const [gx, gy] = proj(0, goalW);
  const gs = (BF * 1.25) / Math.max(0.3, goalW - wc);
  const crownW = gs * 0.6;
  const onPawn = crownDrop;
  const cx = gx * (1 - onPawn) + bx * onPawn, cyTop = (gy - gs * 1.35 + 8 * Math.sin(t * 2)) * (1 - onPawn) + (by - ph - ph * 0.36 + ph * 0.06) * onPawn;
  const cw = crownW * (1 - onPawn) + ph * 0.6 * onPawn;
  return (
    <AbsoluteFill style={{ opacity: enter * (1 - exit) }}>
      <Glow x={gx} y={gy - gs} r={300 + 200 * crownIn} a={0.3 * crownIn} />
      <svg width={1080} height={1920} style={{ position: "absolute", inset: 0 }}>{sq}</svg>
      {obs.map(([W, a, out, side], i) => {
        const up = k(t, a, 0.4), away = io(t, out, out + 0.45);
        const [ox, oy] = proj(side * 1.6 * away, W);
        const oh = (BF * 1.3) / Math.max(0.3, W - wc);
        if (up <= 0 || W - wc < 0.4) return null;
        return <div key={i} style={{ position: "absolute", left: ox - (oh * 50) / 140, top: oy - oh * up, height: oh * up, overflow: "hidden", opacity: 1 - lin(t, out + 0.2, out + 0.6) }}><RookDark h={oh} /></div>;
      })}
      <Glow x={bx} y={by - ph * 0.5} r={ph * 1.1} a={0.12 + 0.3 * crownDrop} />
      <div style={{ position: "absolute", left: bx - (ph * 50) / 140, top: by - ph - hop * 46 - 700 * Math.pow(1 - k(t, 21.3, 0.55), 2), filter: "drop-shadow(0 0 24px rgba(255,210,140,0.4))", opacity: Math.min(1, k(t, 21.3, 0.3) * 2) }}>
        <Pawn h={ph} id="jree-p3" />
      </div>
      <div style={{ position: "absolute", left: cx - cw / 2, top: cyTop, opacity: crownIn, filter: `blur(${((1 - crownIn) * 10).toFixed(1)}px) drop-shadow(0 0 20px rgba(255,214,150,0.55))` }}>
        <Crown w={cw} id="jree-c2" />
      </div>
      <AbsoluteFill style={{ background: "#FFE9BF", opacity: flash, mixBlendMode: "screen" }} />
      <TopShade />
      <Block>
        <Line t={t} at={21.36} out={24.8} size={84} segs={[["Quem tem "], ["estratégia", true]]} />
        <Line t={t} at={23.32} out={24.8} size={84} segs={[["não anda "], ["às cegas.", true]]} />
      </Block>
      <Block>
        <Line t={t} at={25.0} out={27.75} size={80} segs={[["Sabe onde "], ["está indo.", true]]} />
        <Line t={t} at={25.85} out={27.75} size={80} segs={[["E quando você sabe"]]} />
        <Line t={t} at={26.75} out={27.75} size={80} segs={[["para onde vai,"]]} />
      </Block>
      <Block>
        <Line t={t} at={27.93} size={80} segs={[["nenhum "], ["obstáculo", true]]} />
        <Line t={t} at={28.85} size={80} segs={[["te desvia do seu"]]} />
        <Line t={t} at={29.6} size={80} segs={[["destino.", true]]} />
      </Block>
    </AbsoluteFill>
  );
};

// ───────── cena 6: a marca ─────────
const Marca: React.FC<{ t: number }> = ({ t }) => {
  const e = k(t, T6 - 0.05, 1.1);
  const sweep = lin(t, T6 + 0.5, T6 + 1.5) + lin(t, T6 + 1.6, T6 + 2.5) + lin(t, T6 + 2.6, T6 + 3.5);
  const W = 640, H = (W * 686) / 712;
  const cam = 1.1 - 0.1 * e + 0.12 * lin(t, T6, T6 + 3.6);
  return (
    <AbsoluteFill style={{ opacity: lin(t, T6 - 0.1, T6 + 0.35), transform: `scale(${cam.toFixed(4)})` }}>
      <Glow y={880} r={640} a={0.2 * e} />
      <div style={{ position: "absolute", left: 540 - W / 2, top: 500, width: W, height: H, opacity: e, filter: `blur(${((1 - e) * 20).toFixed(1)}px)`, transform: `scale(${(1.4 - 0.4 * e).toFixed(4)}) rotate(${(6 * (1 - e)).toFixed(2)}deg)` }}>
        <Img src={staticFile("jre-e/logo.png")} style={{ width: W, height: H }} />
        <div style={{ position: "absolute", inset: 0, WebkitMaskImage: `url(${staticFile("jre-e/logo.png")})`, WebkitMaskSize: "100% 100%",
          background: `linear-gradient(105deg, transparent ${((sweep % 1.0001) * 160 - 40).toFixed(1)}%, rgba(255,246,220,0.85) ${((sweep % 1.0001) * 160 - 25).toFixed(1)}%, transparent ${((sweep % 1.0001) * 160 - 10).toFixed(1)}%)`, mixBlendMode: "screen" }} />
      </div>
      <div style={{ position: "absolute", left: 120, right: 120, top: 1230, textAlign: "center", fontFamily: CAPS, fontWeight: 500, fontSize: 62, letterSpacing: "0.22em", marginRight: "-0.22em", ...gold(t, 0.2), ...blurIn(t, T6 + 0.75) }}>DO PEÃO AO REI</div>
      <div style={{ position: "absolute", left: 540 - 260 * k(t, T6 + 1.1, 0.9), width: 520 * k(t, T6 + 1.1, 0.9), top: 1336, height: 2, background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />
      <div style={{ position: "absolute", left: 120, right: 120, top: 1372, textAlign: "center", fontFamily: CAPS, fontWeight: 400, fontSize: 25, letterSpacing: "0.3em", color: CREAM, opacity: 0.85, ...blurIn(t, T6 + 1.3) }}>FEITO PARA QUEM DITA AS REGRAS.</div>
    </AbsoluteFill>
  );
};

export const EstrategiaV2: React.FC = () => {
  const frame = useCurrentFrame();
  const t = toV1(frame / JREE_FPS - LEAD);
  const near = (a: number, b: number) => t > a - 0.8 && t < b + 0.8;
  return (
    <AbsoluteFill style={{ background: BG, overflow: "hidden" }}>
      {near(-1, T2) && <Abertura t={t} />}
